package com.shopsphere.dao;
import com.shopsphere.model.*;
import com.shopsphere.util.DBConnection;
import java.math.BigDecimal;
import java.sql.*;
import java.util.*;
import java.util.logging.*;
public class OrderDAO {
    private static final Logger LOGGER = Logger.getLogger(OrderDAO.class.getName());
    public Order findById(Long id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT o.*, u.name AS user_name, u.email AS user_email FROM orders o JOIN users u ON o.user_id=u.id WHERE o.id=?")) { p.setLong(1, id); try (ResultSet r = p.executeQuery()) { if (r.next()) { Order o = map(r); o.setItems(findItemsByOrderId(o.getId())); return o; } } } catch (SQLException e) {} return null; }
    public Order findByOrderNumber(String num) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT o.*, u.name AS user_name, u.email AS user_email FROM orders o JOIN users u ON o.user_id=u.id WHERE o.order_number=?")) { p.setString(1, num); try (ResultSet r = p.executeQuery()) { if (r.next()) { Order o = map(r); o.setItems(findItemsByOrderId(o.getId())); return o; } } } catch (SQLException e) {} return null; }
    public List<Order> findByUserId(Long userId) { List<Order> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT o.*, u.name AS user_name, u.email AS user_email FROM orders o JOIN users u ON o.user_id=u.id WHERE o.user_id=? ORDER BY o.id DESC")) { p.setLong(1, userId); try (ResultSet r = p.executeQuery()) { while (r.next()) { Order o = map(r); o.setItems(findItemsByOrderId(o.getId())); l.add(o); } } } catch (SQLException e) {} return l; }
    public List<Order> findAllForAdmin() { List<Order> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT o.*, u.name AS user_name, u.email AS user_email FROM orders o JOIN users u ON o.user_id=u.id ORDER BY o.id DESC"); ResultSet r = p.executeQuery()) { while (r.next()) { Order o = map(r); o.setItems(findItemsByOrderId(o.getId())); l.add(o); } } catch (SQLException e) {} return l; }
    public boolean placeOrderTransaction(Order order, List<OrderItem> items, Payment payment, Long cartIdToClear) {
        Connection c = null;
        try {
            c = DBConnection.getConnection();
            c.setAutoCommit(false);
            for (OrderItem item : items) {
                try (PreparedStatement ch = c.prepareStatement("SELECT stock FROM products WHERE id=? FOR UPDATE")) { ch.setLong(1, item.getProductId()); try (ResultSet r = ch.executeQuery()) { if (!r.next() || r.getInt("stock") < item.getQuantity()) { c.rollback(); return false; } } }
                try (PreparedStatement d = c.prepareStatement("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?")) { d.setInt(1, item.getQuantity()); d.setLong(2, item.getProductId()); d.setInt(3, item.getQuantity()); if (d.executeUpdate() <= 0) { c.rollback(); return false; } }
            }
            long orderId;
            try (PreparedStatement p = c.prepareStatement("INSERT INTO orders (order_number,user_id,recipient_name,recipient_phone,shipping_address,subtotal,discount_amount,shipping_fee,total_amount,order_status,payment_status,payment_method,coupon_code) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) {
                p.setString(1, order.getOrderNumber()); p.setLong(2, order.getUserId()); p.setString(3, order.getRecipientName()); p.setString(4, order.getRecipientPhone()); p.setString(5, order.getShippingAddress()); p.setBigDecimal(6, order.getSubtotal()); p.setBigDecimal(7, order.getDiscountAmount()); p.setBigDecimal(8, order.getShippingFee()); p.setBigDecimal(9, order.getTotalAmount()); p.setString(10, order.getOrderStatus().name()); p.setString(11, order.getPaymentStatus().name()); p.setString(12, order.getPaymentMethod()); p.setString(13, order.getCouponCode());
                if (p.executeUpdate() <= 0) { c.rollback(); return false; }
                try (ResultSet k = p.getGeneratedKeys()) { if (k.next()) { orderId = k.getLong(1); order.setId(orderId); } else { c.rollback(); return false; } }
            }
            try (PreparedStatement p = c.prepareStatement("INSERT INTO order_items (order_id,product_id,product_name,unit_price,discount_applied,quantity,subtotal) VALUES (?,?,?,?,?,?,?)")) { for (OrderItem it : items) { p.setLong(1, orderId); p.setLong(2, it.getProductId()); p.setString(3, it.getProductName()); p.setBigDecimal(4, it.getUnitPrice()); p.setBigDecimal(5, it.getDiscountApplied()); p.setInt(6, it.getQuantity()); p.setBigDecimal(7, it.getSubtotal()); p.addBatch(); } p.executeBatch(); }
            if (payment != null) { try (PreparedStatement p = c.prepareStatement("INSERT INTO payments (order_id,amount,method,status,transaction_ref) VALUES (?,?,?,?,?)")) { p.setLong(1, orderId); p.setBigDecimal(2, payment.getAmount()); p.setString(3, payment.getMethod()); p.setString(4, payment.getStatus().name()); p.setString(5, payment.getTransactionRef()); p.executeUpdate(); } }
            if (order.getCouponCode() != null && !order.getCouponCode().isBlank()) { try (PreparedStatement p = c.prepareStatement("UPDATE coupons SET times_used=times_used+1 WHERE code=?")) { p.setString(1, order.getCouponCode().trim().toUpperCase()); p.executeUpdate(); } }
            if (cartIdToClear != null && cartIdToClear > 0) { try (PreparedStatement p = c.prepareStatement("DELETE FROM cart_items WHERE cart_id=?")) { p.setLong(1, cartIdToClear); p.executeUpdate(); } }
            c.commit();
            return true;
        } catch (SQLException e) { if (c != null) try { c.rollback(); } catch (SQLException ex) {} return false; } finally { if (c != null) try { c.setAutoCommit(true); c.close(); } catch (SQLException ex) {} }
    }
    public boolean updateOrderStatus(Long orderId, Order.OrderStatus status) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE orders SET order_status=? WHERE id=?")) { p.setString(1, status.name()); p.setLong(2, orderId); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public boolean updatePaymentStatus(Long orderId, Order.PaymentStatus status) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE orders SET payment_status=? WHERE id=?")) { p.setString(1, status.name()); p.setLong(2, orderId); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public List<OrderItem> findItemsByOrderId(Long orderId) { List<OrderItem> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT oi.*, p.image_url FROM order_items oi LEFT JOIN products p ON oi.product_id=p.id WHERE oi.order_id=?")) { p.setLong(1, orderId); try (ResultSet r = p.executeQuery()) { while (r.next()) { OrderItem it = new OrderItem(); it.setId(r.getLong("id")); it.setOrderId(r.getLong("order_id")); it.setProductId(r.getLong("product_id")); it.setProductName(r.getString("product_name")); it.setProductImageUrl(r.getString("image_url")); it.setUnitPrice(r.getBigDecimal("unit_price")); it.setDiscountApplied(r.getBigDecimal("discount_applied")); it.setQuantity(r.getInt("quantity")); it.setSubtotal(r.getBigDecimal("subtotal")); l.add(it); } } } catch (SQLException e) {} return l; }
    public int countTotalOrders() { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT COUNT(*) FROM orders"); ResultSet r = p.executeQuery()) { if (r.next()) return r.getInt(1); } catch (SQLException e) {} return 0; }
    public BigDecimal calculateTotalRevenue() { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE order_status!='CANCELLED'"); ResultSet r = p.executeQuery()) { if (r.next()) return r.getBigDecimal(1); } catch (SQLException e) {} return BigDecimal.ZERO; }
    private Order map(ResultSet r) throws SQLException { Order o = new Order(); o.setId(r.getLong("id")); o.setOrderNumber(r.getString("order_number")); o.setUserId(r.getLong("user_id")); try { o.setUserName(r.getString("user_name")); o.setUserEmail(r.getString("user_email")); } catch (SQLException e) {} o.setRecipientName(r.getString("recipient_name")); o.setRecipientPhone(r.getString("recipient_phone")); o.setShippingAddress(r.getString("shipping_address")); o.setSubtotal(r.getBigDecimal("subtotal")); o.setDiscountAmount(r.getBigDecimal("discount_amount")); o.setShippingFee(r.getBigDecimal("shipping_fee")); o.setTotalAmount(r.getBigDecimal("total_amount")); o.setOrderStatus(Order.OrderStatus.valueOf(r.getString("order_status"))); o.setPaymentStatus(Order.PaymentStatus.valueOf(r.getString("payment_status"))); o.setPaymentMethod(r.getString("payment_method")); o.setCouponCode(r.getString("coupon_code")); o.setCreatedAt(r.getTimestamp("created_at")); return o; }
}
